parameters.functionCode:
const data = items[0].json;
const name = data.personal_info.name || "Friend";
const goals = data.health_dietary_preferences.nutritional_goals;
const cuisine = data.meal_preferences.cuisine_preferences.join(", ");
const meals = data.meal_preferences.meals_per_day;
const dislikes = data.meal_preferences.disliked_foods;

return [{
  json: {
    message: `Hi ${name}, here’s your custom plan!\n\nGoal: ${goals}\nPreferred Cuisine: ${cuisine}\nMeals/Day: ${meals}\nAvoid: ${dislikes}`
  }
}];

parameters.prompt:
You are a nutritionist. Based on the following user data, generate a 3-day personalized meal plan (breakfast, lunch, dinner) tailored to their needs, restrictions, and preferences. Present it in clean, readable format with bullet points.

User data:
Name: {{$json["personal_info"]["name"]}}
Age Range: {{$json["personal_info"]["age_range"]}}
Gender: {{$json["personal_info"]["gender"]}}
Medical Conditions: {{$json["health_dietary_preferences"]["medical_conditions"].join(", ")}}
Allergies: {{$json["health_dietary_preferences"]["allergies"].join(", ")}}
Dietary Restrictions: {{$json["health_dietary_preferences"]["dietary_restrictions"].join(", ")}}
Nutritional Goals: {{$json["health_dietary_preferences"]["nutritional_goals"]}}
Meals Per Day: {{$json["meal_preferences"]["meals_per_day"]}}
Cuisines: {{$json["meal_preferences"]["cuisine_preferences"].join(", ")}}
Disliked Foods: {{$json["meal_preferences"]["disliked_foods"]}}
Meal Types: {{$json["meal_preferences"]["preferred_meal_types"].join(", ")}}
Cooking Skill Level: {{$json["cooking_lifestyle_habits"]["cooking_skill_level"]}}
Kitchen Equipment: {{$json["cooking_lifestyle_habits"]["available_kitchen_equipment"].join(", ")}}
